using System;
using System.IO;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using Newtonsoft.Json.Linq;
using LastRail.Battle;
using LastRail.Run;
namespace LastRail.Tests.EditMode {public sealed class BOriginalEventProducerTests {
 const string Qa="D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BOriginalEventProducer-20261006/";
 [Test] public void OriginalNativeOwnerMustExposeVersionedEventFactoryAndImmutableEventJournal(){Assert.NotNull(typeof(BDirectAttackBasicLoop).GetMethod("CreateOrdinaryTravelEventRuntime"));Assert.NotNull(typeof(BDirectAttackBasicLoop).GetMethod("CaptureOriginalEvents"));}
 static JObject Rail(){var c=global::CombatRailJourneyTests.Config();c["offers"]=new JArray();c["throttleMaximumBps"]=13000;c["throttleCruiseBps"]=10000;return c;}
 [Test] public void NewCaptureRestoresExactlyAndLegacyNeverRetroactivelyClaimsEvents(){var f=BNamedOperatorSourceTests.Native();var node=BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource;var g=BOrdinaryGeometryTests.Geometry(f.binding);var c=Rail();foreach(bool modern in new[]{false,true}){var n=modern?BDirectAttackBasicLoop.CreateOrdinaryTravelEventRuntime(f.binding,node,g,10000,c,BDirectAttackInput.Digest(c)):BDirectAttackBasicLoop.CreateOrdinaryTravelRuntime(f.binding,node,g,10000,c,BDirectAttackInput.Digest(c));n.Advance("original-step",10000000,500);var snapshot=n.Capture();Assert.AreEqual(modern?BDirectAttackBasicLoop.TravelEventVersion:BDirectAttackBasicLoop.TravelVersion,(string)snapshot["version"]);var r=BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(snapshot,BDirectAttackInput.Digest(snapshot),f.binding,node,g,10000,c,BDirectAttackInput.Digest(c));Assert.IsTrue(JToken.DeepEquals(snapshot,r.Capture()));Assert.AreEqual(modern,n.CaptureOriginalEvents()!=null);n.SetPaused("hold",true);r.SetPaused("hold",true);Assert.IsTrue(JToken.DeepEquals(n.Capture(),r.Capture()));n.SetPaused("hold",true);Assert.IsTrue(JToken.DeepEquals(n.Capture(),r.Capture()));var before=n.Capture();Assert.Throws<ArgumentException>(()=>n.SetPaused("hold",false));Assert.IsTrue(JToken.DeepEquals(before,n.Capture()));}}
 [Test] public void RejectedStagedAdvanceCannotPublishEventJournalOrOtherOwnerState(){var f=BNamedOperatorSourceTests.Native();var node=BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource;var g=BOrdinaryGeometryTests.Geometry(f.binding);var c=Rail();var n=BDirectAttackBasicLoop.CreateOrdinaryTravelEventRuntime(f.binding,node,g,10000,c,BDirectAttackInput.Digest(c));var flags=BindingFlags.Instance|BindingFlags.NonPublic;var travel=typeof(BDirectAttackBasicLoop).GetField("travel",flags).GetValue(n);var motion=travel.GetType().GetField("motion",flags).GetValue(travel);typeof(CombatRailJourney).GetField("distanceMm",flags).SetValue(motion,long.MaxValue);var before=n.Capture();Assert.Throws<OverflowException>(()=>n.Advance("staged-fault",10000000,500));Assert.IsTrue(JToken.DeepEquals(before,n.Capture()));Assert.AreEqual(0,((JArray)n.CaptureOriginalEvents()["records"]).Count);}
 [Test] public void RehashedChangedJournalFailsOriginalReplay(){var f=BNamedOperatorSourceTests.Native();var node=BInterceptSourceTests.Read(BInterceptSourceTests.Sample()).OriginalSource;var g=BOrdinaryGeometryTests.Geometry(f.binding);var c=Rail();var n=BDirectAttackBasicLoop.CreateOrdinaryTravelEventRuntime(f.binding,node,g,10000,c,BDirectAttackInput.Digest(c));n.Advance("short-prefix",1000000,50);var changed=n.Capture();changed["originalEvents"]["records"]=new JArray(new JObject{["eventRef"]="forged"});Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(changed,BDirectAttackInput.Digest(changed),f.binding,node,g,10000,c,BDirectAttackInput.Digest(c)));}
 [Test,Timeout(300000)] public void OriginalTwoWaveCommandsCaptureEachOccurrenceInsteadOfFinalCommandCheckpoint(){
  // Re-execute preserved original commands from tick zero, without HTTP or importing old event checkpoints.
  var old=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BNativeTwoWave-20261005/two-wave-http-result.json"));var packet=(JObject)old["sourceBundle"];var bundle=BNativeNodeSourceSnapshot.Read(packet.ToString(),(string)packet["packetHash"],(string)packet["accountId"],(string)packet["runId"]);var b=BRouteNativeTests.Binding(bundle.Boarding);var g=BOrdinaryGeometryTests.Geometry(b);var prior=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BNativeHttp-20261005/actual-http-native.json"));var rail=(JObject)prior["motion"];var n=BDirectAttackBasicLoop.CreateOrdinaryTravelEventRuntime(b,bundle.Boarding,g,10000,rail,BDirectAttackInput.Digest(rail));var commands=(JArray)old["controller"]["nodeSession"]["runtime"]["commands"];var commit=typeof(BDirectAttackBasicLoop).GetMethod("Commit",BindingFlags.Instance|BindingFlags.NonPublic);
  foreach(var command in commands)commit.Invoke(n,new object[]{(JObject)command.DeepClone(),null});
  Assert.AreEqual("VICTORY",n.Outcome);var journal=n.CaptureOriginalEvents();var rows=(JArray)journal["records"];Assert.AreEqual(3,rows.Count);var waves=rows.Where(x=>(string)x["binding"]["kind"]=="WAVE_CLEAR").ToArray();Assert.AreEqual(2,waves.Length);Assert.AreEqual(8060,(long)waves[0]["binding"]["rawEvent"]["tick"]);Assert.AreEqual(14435,(long)waves[1]["binding"]["rawEvent"]["tick"]);
  foreach(var row in rows){var binding=(JObject)row["binding"];var point=(JObject)row["checkpoint"];Assert.AreEqual(BDirectAttackInput.Digest(binding),(string)row["eventRef"]);Assert.AreEqual(BDirectAttackInput.Digest(point),(string)binding["checkpointHash"]);int revision=(int)binding["commandRevision"];Assert.IsTrue(JToken.DeepEquals(commands[revision-1],binding["originalCommand"]));Assert.AreEqual((long)binding["rawEvent"]["tick"],(long)point["tick"]);Assert.AreEqual((long)point["tick"],(long)point["state"]["direct"]["clock"]["completedSteps"]);Assert.AreEqual((long)point["tick"],(long)point["travel"]["motion"]["currentTick"]);Assert.IsNull(point["originalEvents"]);}
  Assert.AreNotEqual("resume-step-362",(string)waves[0]["binding"]["originalCommand"]["eventId"]);Assert.Less((long)waves[0]["checkpoint"]["tick"],n.Tick);Assert.AreEqual("TERMINAL",(string)rows.Last["binding"]["kind"]);Assert.IsFalse(rows.Any(x=>(string)x["binding"]["kind"]=="ARRIVE"));Assert.IsTrue(n.ObserveResidualHazards().Settled);
  var saved=n.Capture();commit.Invoke(n,new object[]{(JObject)commands.Last.DeepClone(),null});Assert.IsTrue(JToken.DeepEquals(saved,n.Capture()));rows[0]["eventRef"]="caller-edited";Assert.AreNotEqual("caller-edited",(string)n.CaptureOriginalEvents()["records"][0]["eventRef"]);
  var restored=BDirectAttackBasicLoop.RestoreOrdinaryTravelRuntime(saved,BDirectAttackInput.Digest(saved),b,bundle.Boarding,g,10000,rail,BDirectAttackInput.Digest(rail));Assert.IsTrue(JToken.DeepEquals(saved,restored.Capture()));n.Advance("after-terminal",10000000,500);restored.Advance("after-terminal",10000000,500);Assert.IsTrue(JToken.DeepEquals(n.Capture(),restored.Capture()));Assert.AreEqual(3,((JArray)n.CaptureOriginalEvents()["records"]).Count);
  File.WriteAllText(Qa+"original-event-sample.json",new JObject{["journal"]=n.CaptureOriginalEvents(),["finalCommandId"]=commands.Last["eventId"].DeepClone(),["finalTick"]=n.Tick,["nativeCaptureVersion"]=saved["version"].DeepClone(),["serverAccepted"]=false,["reexecutedPreservedCommandsFromStart"]=true}.ToString());
 }
